"""Role-specific company reports derived from project state, never chat transcripts."""
import datetime
from scenarios import PEOPLE,stage
import learning
BASE=[
 ('stock','Inventory availability','Inventory and order commitments use the approved business rule.','Elena / delivery team',2),
 ('migration','Migration assurance','Opening stock and mappings are verified across three warehouses.','Nikhil / implementation team',3),
 ('implementation','Order workflow','The agreed inventory and order workflows are implemented and verified.','Implementation team',5),
 ('verification','Release verification','Cross-site checks support the agreed release coverage.','Nikhil',9),
 ('training','User readiness','Warehouse users can perform the agreed operational workflows.','Rosa',11)]
# These describe observed commitments, not inferred intentions.
ERRORS={
 'physical':('Stock allocation instruction','Order promises were authorized against physical stock without excluding existing reservations and quarantine.','Orders could consume unavailable stock.','Obtain an accepted allocation rule and verify the implementation.'),
 'quarantine':('Quarantined stock included','The allocation instruction included stock awaiting authorized release.','The instruction does not protect unavailable stock.','Correct the rule and test quarantine behavior.'),
 'delegate_policy':('Business authority unresolved','Client business policy was delegated to the implementer.','The client approval boundary was not established.','Obtain sponsor approval for the proposed rule.'),
 'promise_all':('Unassessed scope commitment','All department requests were promised against the original deadline without a capacity or funding agreement.','Delivery expectations exceed the assessed baseline.','Reconcile acceptance priorities, scope, capacity and the delivery commitment.'),
 'overstate':('Readiness claim exceeded evidence','The prototype was described as nearly finished before production readiness was established.','The readiness claim exceeds the available acceptance evidence.','Clarify demonstration limits and obtain the missing readiness evidence.'),
 'blind':('Response committed before capacity review','The changed conditions were accepted before their capacity impact was checked.','The response lacks an assessed delivery basis.','Reconcile remaining commitments and a feasible response.'),
 'skip_data':('Migration verification omitted','Supplied records were used without additional checking after duplicate-record risk was raised.','Migrated quantities remain unsupported.','Verify the data before unrestricted acceptance.'),
 'minimum_tests':('Verification coverage not funded','Additional release checks were omitted.','Full release evidence remains incomplete.','Execute the required checks or agree a bounded completion plan.'),
 'minimum_training':('Readiness limited to handover','Standard handover was selected without establishing warehouse rehearsal coverage.','Three-site user readiness is not demonstrated.','Arrange verified operational practice or an accepted completion plan.'),
 'conceal':('Material finding omitted from reporting','An unresolved finding was excluded from the reported project position.','Stakeholders lack the recorded readiness limitation.','Correct the status report and resolve or explicitly agree the outstanding work.'),
 'false_ready':('Unsupported readiness declaration','Readiness was declared while acceptance gates remained unresolved.','Release reporting exceeds the recorded completion evidence.','Correct the declaration and reconcile the remaining gates.'),
 'forced':('Unvalidated schedule commitment','The forty-eight-hour demand was accepted without changing the delivery conditions.','The commitment does not reconcile validation and capacity.','Renegotiate a supported sequence with the decision owners.'),
 'shame':('Unbounded overtime demand','Work was demanded until completion without an agreed availability boundary.','The team did not agree unlimited overtime.','Agree bounded cover, priorities and a stopping point.')}
RESOLVED_BY={'physical':'stock','quarantine':'stock','delegate_policy':'stock','skip_data':'migration','minimum_tests':'verification','minimum_training':'training'}
def date(s):return (datetime.date.fromisoformat(s['start'])+datetime.timedelta(days=int(s['day']))).isoformat()
def report(s,mentor=False):
 f=s['flags'];keys={h['step']:h['key'] for h in s['history']};facts=learning.known(s)
 seen=max([m['step'] for m in s['messages'] if m['id'] in s['read_ids'] and m['who']!='alex' and m['thread']!='mentor'] or [0])
 def visible(step):return mentor or seen>=step or step in keys
 complete={'stock':bool(f.get('rule')),'migration':bool(f.get('data')),'implementation':5 in keys and bool(f.get('tests')) and not f.get('defect',False),'verification':bool(f.get('tests')),'training':bool(f.get('training'))}
 rows=[]
 for ident,name,scope,owner,step in BASE:
  if not visible(step) and not (ident in ('stock','implementation') or 'budget' in facts):continue
  done=complete[ident];position='Not started; planning outstanding';remaining='Define the work, owner and verification basis.'
  if ident=='stock':
   position='Client rule approved' if done else 'Client rule not yet confirmed'
   remaining='No outstanding rule approval; maintain the approved boundary.' if done else 'Confirm the allocation rule with the client and test its behavior.'
  elif ident=='migration':
   position='Three-site audit and mapping review complete' if done else 'Sample coverage only; unrestricted migration remains unverified' if keys.get(3)=='sample' else 'Data verification outstanding'
   remaining='Maintain the reviewed mapping and audit record.' if done else 'Complete the required data checks or obtain acceptance for a bounded pilot.'
  elif ident=='implementation':
   position='Working workflows supported by release checks' if done else 'Demonstration build available; production acceptance unconfirmed' if visible(5) else 'Implementation preparation'
   remaining='Complete final acceptance and authorized handover.' if done else 'Implement and verify the agreed workflow before production acceptance.'
  elif ident=='verification':
   position='Agreed release coverage verified' if done else 'Pilot evidence only' if f.get('pilot_tests') else 'Cross-site verification outstanding'
   remaining='Retain the test and release record.' if done else 'Execute and review the remaining checks for the agreed coverage.'
  elif ident=='training':
   position='Cross-site readiness established' if done else 'Pilot preparation only' if f.get('pilot_training') else 'User preparation outstanding'
   remaining='Maintain operational support and ownership.' if done else 'Confirm owners, materials and operational rehearsal coverage.'
  rows.append(dict(id=ident,workstream=name,scope=scope,owner=owner,status='complete' if done else 'pending',position=position,remaining=remaining))
 for ident,name,scope,step,done in [('alerts','Exception alerts','Deliver the additional alert scope agreed with the client.',6 if f.get('event')=='scope' else 13,bool(f.get('recovered')) and (f.get('event')=='scope' or 13 in keys)),('legacy','Legacy interface','Integrate and validate the newly agreed legacy interface.',13,f.get('hard_complete'))]:
  active=(ident=='alerts' and (f.get('event')=='scope' or f.get('pressure')=='hard')) or (ident=='legacy' and f.get('pressure')=='hard')
  if active and visible(step):rows.append(dict(id=ident,workstream=name,scope=scope,owner='Client / specialist team',status='complete' if done else 'pending',position='Agreed work completed' if done else 'Additional agreed work outstanding',remaining='Retain acceptance evidence.' if done else 'Confirm funded implementation and validation before acceptance.'))
 commitments=[]
 summaries={1:'Implementation staffing appointed; business commitments remain with Alex.',4:'Acceptance priorities and change boundaries recorded.' if keys.get(4)=='priorities' else 'All department requests included in the delivery commitment.',5:'Demonstration delivered with stated production limitations.' if keys.get(5)=='honest' else 'Progress represented as nearly complete.',7:'Response to the changed operating conditions authorized.',8:'Team availability and workload approach recorded.',12:'Committee position reported.',14:'Client completion agreement recorded.',15:'Release decision recorded.'}
 for h in s['history']:
  if h['step'] in summaries:commitments.append(dict(date=h['date'],summary=summaries[h['step']]))
 if f.get('agreement'):
  commitments.append(dict(date=date(s),summary={'full_accept':'Full release agreed against the acceptance record.','phase_accept':'Phased completion agreed with funded validation and training.','delay_accept':'Revised completion date and recovery package agreed.','stop_accept':'Orderly stop requested because the remaining scope could not be funded.'}.get(f['agreement'],'Completion plan recorded.')))
 pending=[dict(workstream=r['workstream'],action=r['remaining'],owner=r['owner'],status='pending') for r in rows if r['status']=='pending']
 outcome=s.get('result');summary='Delivery accepted against the agreed completion plan.' if outcome and outcome['delivered'] else 'Delivery not accepted; consult outstanding requirements and exceptions.' if outcome else 'Production acceptance remains unconfirmed. Completion is tracked separately from demonstration progress.'
 return dict(title='Delivery Oversight Report' if mentor else 'Meridian Project Status Report',date=date(s),owner='Daniel Mercer — oversight' if mentor else 'Alex Rao — delivery',summary=summary,rows=rows,pending=pending,commitments=commitments,budget=dict(authorization=s['authorization'],committed=s['spent'],available=s['authorization']-s['spent'],reserve_drawn=s['drawn']),deadline=(datetime.date.fromisoformat(s['start'])+datetime.timedelta(days=f.get('accepted_deadline',112))).isoformat(),original_deadline=(datetime.date.fromisoformat(s['start'])+datetime.timedelta(days=112)).isoformat())
def exceptions(s):
 r=report(s,True);rows=[]
 for h in s['history']:
  key=h['key']
  if key in ERRORS:
   title,event,impact,action=ERRORS[key];resolved=RESOLVED_BY.get(key) and any(x['id']==RESOLVED_BY[key] and x['status']=='complete' for x in r['rows'])
   resolved=bool(resolved or (key=='promise_all' and s['flags'].get('agreement') in ('phase_accept','delay_accept')) or (key=='overstate' and s['flags'].get('transparent')) or (key=='blind' and s['flags'].get('recovered')))
   rows.append(dict(kind='Decision exception',status='resolved' if resolved else 'issue',title=title,observed=event,impact=impact,action='Correction evidence recorded; retain the original decision for review.' if resolved else action,step=h['step'],date=h['date'],basis='Observed commitment and project evidence; intent and comprehension are unconfirmed.'))
  missing=[o for o in s.get('opportunities',[]) if o['step']==h['step'] and o['status']=='expired']
  if missing:rows.append(dict(kind='Information gap',status='pending',title='Available clarification not consulted',observed=f"{len(missing)} introduced information discussion(s) expired before the commitment.",impact='The recorded decision was made without those optional confirmations. This alone is not a confirmed mistake.',action='Revisit relevant uncertainty before the next dependent commitment.',step=h['step'],date=h['date'],basis='Observed consultation record; no inference about personality or intent.'))
 if s['flags'].get('rushed_feedback'):
  rows.append(dict(kind='Observed consequence',status='resolved' if s['flags'].get('feedback_rework_done') else 'pending',title='Expedited intern work',observed='A bounded batch completed one working day sooner.' if any(h['step']==7 for h in s['history']) else 'The feedback instruction requested faster completion; the next batch has not yet been completed.',impact='Mapping correction and review required three working days.' if s['flags'].get('feedback_rework_done') else 'Quality outcomes have not yet been established.',action='Retain correction evidence and verify the next batch.' if s['flags'].get('feedback_rework_done') else 'Monitor actual verification results; do not infer an unobserved consequence.',step=5,date=date(s),basis='Recorded instruction and observed work only.'))
 return dict(title='Pending Actions and Decision Exceptions',findings=rows,pending=r['pending'],lookahead='A steering review is awaiting your input.' if s['pending'] else 'A steering review is approaching; review current completion evidence.' if s['step'] in (4,5,11,12) else 'Continue monitoring the current delivery position. Future constraints and solution paths are withheld.',note='Yellow identifies unfinished work or an information gap. Red identifies a documented decision exception; neither color alone establishes intent or management quality.')


def decision_summary(s):
 titles=['Staffing','Stock allocation','Data migration','Acceptance priorities','Demonstration','Changed conditions','Recovery plan','Team capacity','Release verification','Readiness finding','User preparation','Status reporting','Leadership review','Completion agreement','Release decision']
 descriptions={'maya':'An experienced specialist was hired.','jordan':'A mid-level implementer was hired.','sam':'A trainee was selected with a need for senior support.','rule':'The client allocation rule was proposed.','physical':'Physical stock was used for order promises.','quarantine':'Quarantined stock was included in the proposed allocation.','delegate_policy':'The business-policy decision was delegated to the implementer.','audit':'A full data audit was authorized.','sample':'A limited sample was chosen.','skip_data':'Additional data checking was skipped.','priorities':'Acceptance priorities were recorded.','promise_all':'All department requests were promised.','honest':'The demonstration was presented with its limits.','overstate':'Progress was presented as nearly complete.','diagnose':'The changed conditions were reviewed before responding.','blind':'A response was promised before checking capacity.','support_people':'A bounded availability and workload plan was chosen.','shame':'Unbounded overtime was demanded.','full_tests':'Full cross-site verification was funded.','pilot_tests':'A limited pilot was selected.','minimum_tests':'Additional release checks were skipped.','lean_tests':'Focused cross-site checks were selected.','repair':'The readiness finding was addressed through additional work.','conceal':'An unresolved finding was omitted from reporting.','full_training':'Cross-site user training was authorized.','pilot_training':'Training was limited to a pilot.','transparent':'The status report included progress and remaining limits.','false_ready':'Readiness was declared despite unresolved gates.','evidence':'A verified delivery sequence was proposed.','forced':'The accelerated demand was accepted without changing conditions.','full_accept':'A full release was proposed.','phase_accept':'A phased completion plan was agreed.','delay_accept':'A revised date and recovery plan were agreed.','stop_accept':'An orderly stop was requested.','launch':'A full rollout was authorized.','finish_phase':'The phased plan was executed.','finish_delay':'The recovery plan was executed.','close':'The project was closed without certifying unmet requirements.'}
 return [dict(step=h['step'],title=titles[h['step']-1],summary=descriptions.get(h['key'],'A project approach was selected; its current effects are reflected in oversight.'),date=h['date']) for h in s['history']]


def decision_context(s):
 if s['opening'] is not None:return dict(title='Upcoming decision: implementation hire',narration='Alex is receiving the project handoff and will choose implementation capacity. You can begin guiding Alex now; he may not have seen all the project messages yet.',briefing=['Base project authorization is $300,000; $180,000 is already committed.','Maya costs $60,000 and works more independently; Jordan costs $30,000 and needs direction; Sam has no added salary and needs teaching and senior review.','Alex retains responsibility for client business decisions.'],facts=[])
 if s.get('result'):return dict(title='Project complete',narration='Alex has reached an ending. Review the project outcome and decisions.',briefing=[],facts=[])
 if s['pending'] in ('operational','leadership'):
  return dict(title='Steering review',narration='Your intervention is pending. Select the current condition in Mentor desk; the following decision briefing will update afterward.',briefing=[],facts=[])
 topics={'roles':'Maya can own complex implementation; Jordan needs direction and review; Sam needs teaching and senior sign-off. Alex retains business commitments.','budget':'The base authorization is $300,000; $180,000 is committed before hiring, verification and training.','authority':'Alex clarified the decision-making authority.','stock':'Of 100 physical units, 30 are reserved and 10 are quarantined; 60 are available for a new order.','policy':'Elena approves business policy; reserved or quarantined stock must not be promised to new orders.','sales':'Alex learned why sales wants visibility of physical stock.','technical':'Alex learned that the quantities can be shown separately.','scope':'Alex identified the client’s essential acceptance priorities.','demo':'Alex clarified the limits of the working demonstration.','reliance':'Elena plans to report progress to the steering group; prototype limits should be clear.','readiness_gap':'Alex learned that independent review has not signed off the example for release.','data':'Alex explored how duplicate records affect migration.','review':'Alex discussed the implementer’s review needs.','negotiation':'Alex explored which commitments can be negotiated.','capacity':'Alex discussed availability and a bounded stopping point.','reuse':'Alex reviewed the conditions for focused verification.','coverage':'Alex learned what cross-site acceptance requires.','finding':'Alex discussed the consequence of the readiness finding.','champions':'Alex explored using internal champions for training.','fatigue':'Alex discussed the effect of fatigue on handover.','challenge':'Alex discussed negotiating a feasible delivery sequence.','acceptance':'Alex reviewed the acceptance requirements.','completion':'Alex explored the remaining work in a completion plan.'}
 fact_step=5 if s.get('reply_bonus') else s['step']
 facts=[topics.get(f,'Alex gathered information about '+f.replace('_',' ')+'.') for f in s['facts'].get(str(fact_step),[]) if not f.startswith('clarified_')]
 pending={'operational':'A steering intervention is waiting for your input.','leadership':'A leadership intervention is waiting for your input.','funding':'A funding request is waiting for your decision.'}
 contexts={1:'Alex must choose who will take on implementation work for the project.',2:'Alex must recommend how available stock should be represented and used for new orders.',3:'Alex must decide how much migration evidence to obtain before relying on the data.',4:'Alex must decide how to handle competing requests and acceptance priorities.',5:'Alex must decide how to present the demonstration and its readiness.',6:'Alex must respond to a change in operating conditions.',7:'Alex must authorize a response to the current project conditions.',8:'Alex must decide how to organize the team’s capacity and workload.',9:'Alex must decide what release verification to fund.',10:'Alex must decide how to respond to the current readiness position.',11:'Alex must decide how to prepare warehouse users.',12:'Alex must decide what to include in the project report.',13:'Alex must respond to the current leadership and client demands.',14:'Alex must seek agreement on a completion plan.',15:'Alex must authorize the appropriate delivery or closure.'}
 narration=pending.get(s['pending'],contexts.get(s['step'],'Alex is considering the next project decision.'))+' Discuss the situation with Alex using the facts gathered; Alex makes the decision.'
 if s.get('reply_bonus'):return dict(title='Feedback to Sam',narration='Alex has learned that Sam’s example is complete but broader readiness checks remain. Discuss how Alex should respond to Sam; Alex makes the choice.',briefing=['Sam completed the example assigned to him. Independent checks identified broader readiness gaps.'],facts=facts)
 baseline={1:['Base authorization: $300,000; $180,000 is committed before the hire.','Maya: $60,000 and experienced; Jordan: $30,000 and needs direction; Sam: no added salary and requires senior support.'],2:['Sales wants visibility of physical stock; operations needs to protect reservations and quarantined stock.','The example has 100 physical units, 30 reserved and 10 quarantined; 60 are available for a new order. Elena approves the business rule.'],3:['Warehouse three has duplicate records; unchecked mappings can distort stock. Full checks and limited sampling have different coverage.'],4:['Departments have submitted requests. Reliable inventory and order flow are essential; additions need a scope and capacity review.'],5:['A working core can be demonstrated; that alone does not establish production acceptance, verified migration or user readiness.'],6:['Daniel has communicated a change or confirmed bounded conditions. Review actual commitments before agreeing a response.'],7:['The project needs a feasible response to the conditions already introduced, with clear ownership and review.'],8:['The team needs a workable capacity plan. Any weekend work requires availability and a stopping point.'],9:['Release evidence must match the agreed site coverage; a pilot cannot be relabeled as full verification.'],10:['A readiness gap needs correction or an explicitly agreed plan; if no defect is known, Alex can consider resilience work.'],11:['The warehouses need people, materials and practice before they can use the system.'],12:['The steering report should distinguish verified results, spending, dates and remaining limits.'],13:['Consider the current client and leadership requirements, decision authority and the evidence needed for a feasible plan.'],14:['Acceptance depends on the agreed scope, evidence, readiness and authorized funding.'],15:['The release or closure must match the agreed plan and actual completion evidence.']}
 return dict(title=stage(s)['title'],narration=narration,briefing=baseline.get(s['step'],[]),facts=facts)
